"""Day-4 EDA figures of the TRAINING sample (D29). Untracked; regenerated by ``eda``.

Agg backend, fixed dpi and no PNG metadata (no timestamp, no software tag). The figures
show the daily series, so they live under the gitignored ``reports/eda/figures/`` (D23).
"""

from __future__ import annotations

from collections.abc import Sequence
from fractions import Fraction
from pathlib import Path

import matplotlib

matplotlib.use("Agg")  # select the non-interactive backend before pyplot is imported

import matplotlib.pyplot as plt
import numpy as np
import pandas as pd
from matplotlib.axes import Axes
from matplotlib.figure import Figure
from scipy import stats

from niftytail import diagnostics as dg
from niftytail import losses as ls

__all__ = ["DPI", "FIGURE_NAMES", "write_exceedance_figures", "write_figures"]

DPI = 110
FIGURE_NAMES = (
    "returns_training.png",
    "returns_hist_qq.png",
    "acf_returns.png",
    "exceedance_timeline.png",
    "inter_exceedance_qq.png",
    "indicator_acf.png",
)
GEOMETRIC_NOTE = "Exp(1) is a continuous approximation of a discrete (geometric) null"


def _save(fig: Figure, path: Path) -> Path:
    fig.tight_layout()
    fig.savefig(path, dpi=DPI, metadata={"Software": None})
    plt.close(fig)
    return path


def _acf_panel(ax: Axes, x: ls.FloatArray, max_lag: int, band_z: Fraction, title: str) -> None:
    rho = dg.acf(x, max_lag)
    lags = np.arange(1, max_lag + 1)
    band = float(band_z) / np.sqrt(x.size)
    ax.vlines(lags, 0, rho, color="tab:blue")
    ax.axhline(0, color="black", linewidth=0.8)
    ax.axhline(band, color="tab:red", linestyle="--", linewidth=0.8)
    ax.axhline(-band, color="tab:red", linestyle="--", linewidth=0.8)
    ax.set_xlabel("lag")
    ax.set_title(f"{title} (band ±{band_z}/√n, i.i.d. null)", fontsize=9)


def write_figures(
    fig_dir: Path,
    dates: pd.DatetimeIndex,
    r: ls.FloatArray,
    *,
    levels: Sequence[Fraction],
    acf_max_lag: int,
    band_z: Fraction,
) -> list[Path]:
    """Write the six training-sample figures to ``fig_dir`` and return their paths."""
    fig_dir.mkdir(parents=True, exist_ok=True)
    t = dates.to_numpy()
    loss = -r
    out: list[Path] = []

    fig, ax = plt.subplots(figsize=(10, 3.5))
    ax.plot(t, r, linewidth=0.5)
    ax.set_title("Training log returns")
    out.append(_save(fig, fig_dir / FIGURE_NAMES[0]))

    fig, (a1, a2) = plt.subplots(1, 2, figsize=(10, 4))
    a1.hist(r, bins=80, density=True)
    a1.set_title("Training returns: histogram")
    z = np.sort((r - r.mean()) / r.std(ddof=1))
    theo = stats.norm.ppf((np.arange(1, r.size + 1) - 0.5) / r.size)
    a2.plot(theo, z, ".", markersize=2)
    a2.plot(theo, theo, color="black", linewidth=0.8)
    a2.set_xlabel("N(0,1) quantile")
    a2.set_ylabel("standardised return")
    a2.set_title("Normal QQ")
    out.append(_save(fig, fig_dir / FIGURE_NAMES[1]))

    fig, axes = plt.subplots(1, 3, figsize=(12, 3.5))
    for axi, (x, name) in zip(axes, ((r, "r"), (np.abs(r), "|r|"), (r**2, "r²")), strict=True):
        _acf_panel(axi, x, acf_max_lag, band_z, f"ACF {name}")
    out.append(_save(fig, fig_dir / FIGURE_NAMES[2]))
    return out + write_exceedance_figures(
        fig_dir, dates, loss, levels=levels, acf_max_lag=acf_max_lag, band_z=band_z
    )


def write_exceedance_figures(
    fig_dir: Path,
    dates: pd.DatetimeIndex,
    loss: ls.FloatArray,
    *,
    levels: Sequence[Fraction],
    acf_max_lag: int,
    band_z: Fraction,
) -> list[Path]:
    """Exceedance timeline, inter-exceedance QQ against Exp(1) and indicator ACF per level.

    The last three of ``FIGURE_NAMES``; also used at ``q*`` by ``threshold-select`` (D36).
    """
    fig_dir.mkdir(parents=True, exist_ok=True)
    t = dates.to_numpy()
    out: list[Path] = []
    k = len(levels)
    masks = [ls.exceedance_mask(loss, ls.tail_threshold(loss, q)) for q in levels]
    fig_t, ax_t = plt.subplots(k, 1, figsize=(10, 1.6 * k), sharex=True, squeeze=False)
    fig_q, ax_q = plt.subplots(1, k, figsize=(4 * k, 4), squeeze=False)
    fig_a, ax_a = plt.subplots(1, k, figsize=(4 * k, 3.5), squeeze=False)
    for i, (q, mask) in enumerate(zip(levels, masks, strict=True)):
        ax_t[i, 0].vlines(t[mask], 0, 1, linewidth=0.6)
        ax_t[i, 0].set_yticks([])
        ax_t[i, 0].set_ylabel(f"q={float(q)}", fontsize=8)
        times = dg.inter_exceedance_times(mask)
        m = times.size
        p_hat = mask.sum() / mask.size
        expq = -np.log(1 - (np.arange(1, m + 1) - 0.5) / m)
        ax_q[0, i].plot(expq, np.sort(p_hat * times), ".", markersize=3)
        ax_q[0, i].plot(expq, expq, color="black", linewidth=0.8)
        ax_q[0, i].set_xlabel("Exp(1) quantile")
        ax_q[0, i].set_ylabel("p̂ · T")
        ax_q[0, i].set_title(f"Inter-exceedance times, q={float(q)}", fontsize=9)
        _acf_panel(ax_a[0, i], mask.astype(np.float64), acf_max_lag, band_z, f"q={float(q)}")
    ax_t[0, 0].set_title("Exceedance timeline (training losses L > u)")
    fig_q.text(0.5, 0.005, GEOMETRIC_NOTE, ha="center", fontsize=8)
    fig_a.suptitle("ACF of the exceedance indicator", fontsize=10)
    out.append(_save(fig_t, fig_dir / FIGURE_NAMES[3]))
    fig_q.tight_layout(rect=(0, 0.04, 1, 1))
    fig_q.savefig(fig_dir / FIGURE_NAMES[4], dpi=DPI, metadata={"Software": None})
    plt.close(fig_q)
    out.append(fig_dir / FIGURE_NAMES[4])
    out.append(_save(fig_a, fig_dir / FIGURE_NAMES[5]))
    return out
